import {FAQ_CASES,runFAQCase} from './faq-cases.js?v=36';
const results=new Map(),root=document.getElementById('faqCases');
for(const item of FAQ_CASES){const card=document.createElement('section');card.className='faq-case';const h=document.createElement('h2');h.textContent=item.title;const p=document.createElement('p');p.textContent=item.scope;const links=document.createElement('nav');links.className='faq-source';for(const page of item.pages){const a=document.createElement('a');a.href='https://infinitythewiki.com/'+page;a.target='_blank';a.rel='noopener noreferrer';a.textContent=page.replaceAll('_',' ')+' ↗';links.append(a);}const button=document.createElement('button');button.textContent='复现：'+item.title;const output=document.createElement('output');output.setAttribute('aria-label',item.title+'结果');output.textContent='未运行';button.onclick=()=>{const r=runFAQCase(item.id);results.set(item.id,r);output.className=r.pass?'faq-pass':'faq-fail';output.textContent=(r.pass?'通过':'发现差异')+'\n'+r.rows.map(x=>(x.pass?'✓ ':'✕ ')+x.label+'：实际 '+JSON.stringify(x.actual)+' / 预期 '+JSON.stringify(x.expected)).join('\n');document.getElementById('faqSummary').textContent=results.size+' / 9 项已复现 · '+[...results.values()].filter(r=>r.pass).length+' 项核心计算通过';};card.append(h,p,links,button,output);root.append(card);}
document.getElementById('runAllFaq').onclick=()=>root.querySelectorAll('button').forEach(b=>b.click());
